package chat

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/golangast/gollemer/internal/ai/analyze"
)

// editsChatFixture builds a tiny project for the assembled-edit
// flow: a string switch, a mode switch whose sibling file holds an
// import to copy, a struct with a positional literal, a map table,
// a generated file, and two same-named structs for ambiguity.
func editsChatFixture(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	write := func(rel, src string) {
		full := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("go.mod", "module example.com/chatedits\n\ngo 1.21\n")
	write("other/other.go", `package other

const (
	ModeFast = 1
	ModeSlow = 2
)
`)
	write("shop/defs.go", `package shop

import other "example.com/chatedits/other"

const ModeDefault = other.ModeFast
`)
	write("shop/shop.go", `package shop

func Describe(kind string) string {
	switch kind {
	case "apple":
		return "a fruit"
	case "carrot":
		return "a vegetable"
	default:
		return "something else"
	}
}

func ModeName(mode int) string {
	switch mode {
	case ModeDefault:
		return "the default mode"
	default:
		return "some other mode"
	}
}

type Config struct {
	Host string
	Port int
}

var DefaultConfig = Config{"localhost", 8080}

var Greetings = map[string]string{
	"hello": "Hello",
	"bye":   "Bye",
}
`)
	write("shop/gen.go", `// Code generated by a tool. DO NOT EDIT.

package shop

func GeneratedPick(kind string) string {
	switch kind {
	case "a":
		return "A"
	default:
		return "?"
	}
}
`)
	write("one/one.go", `package one

type State struct {
	On bool
}
`)
	write("two/two.go", `package two

type State struct {
	Ready bool
}
`)
	return dir
}

// withEditsProject points the chat's project globals at the fixture
// for the duration of a test.
func withEditsProject(t *testing.T, dir string) {
	t.Helper()
	oldProj, oldRoot, oldURoot := lastAnalyzeProject, lastAnalyzeRoot, unifiedProjectRoot
	t.Cleanup(func() { lastAnalyzeProject, lastAnalyzeRoot, unifiedProjectRoot = oldProj, oldRoot, oldURoot })
	p, err := analyze.Analyze(dir)
	if err != nil {
		t.Fatalf("Analyze fixture: %v", err)
	}
	lastAnalyzeProject = p
	lastAnalyzeRoot = dir
	unifiedProjectRoot = dir
}

func yes(string) (string, error) { return "y", nil }
func no(string) (string, error)  { return "n", nil }
func eof(string) (string, error) { return "", errors.New("EOF") }
func readBack(t *testing.T, dir, rel string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, rel))
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// Every documented sentence form parses to the request it names.
func TestParseAssembledEditForms(t *testing.T) {
	cases := []struct {
		line string
		want analyze.EditRequest
	}{
		{`add a "plum" case to Describe`, analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Describe", CaseExpr: `"plum"`}},
		{"add a plum case to Describe", analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Describe", CaseExpr: "plum"}},
		{"add a case for plum to Describe function", analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Describe", CaseExpr: "plum"}},
		{"in Describe also handle plum", analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Describe", CaseExpr: "plum"}},
		{"add a slow case to the switch on mode in Route", analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Route", SwitchOn: "mode", CaseExpr: "slow"}},
		{"add a Timeout field to Config", analyze.EditRequest{Kind: analyze.EditAddField, FieldName: "Timeout", FieldType: "", StructName: "Config"}},
		{"add a Timeout field of type int to Config", analyze.EditRequest{Kind: analyze.EditAddField, FieldName: "Timeout", FieldType: "int", StructName: "Config"}},
		{"add an int field Timeout to the Config struct", analyze.EditRequest{Kind: analyze.EditAddField, FieldName: "Timeout", FieldType: "int", StructName: "Config"}},
		{"add a Name field of type string to Config after Host", analyze.EditRequest{Kind: analyze.EditAddField, FieldName: "Name", FieldType: "string", StructName: "Config", AfterField: "Host"}},
		{"register thanks in Greetings", analyze.EditRequest{Kind: analyze.EditRegister, TableName: "Greetings", Key: "thanks"}},
		{`register "thanks" in the Greetings table`, analyze.EditRequest{Kind: analyze.EditRegister, TableName: "Greetings", Key: "thanks"}},
		{"add 8080 to the Ports list", analyze.EditRequest{Kind: analyze.EditRegister, TableName: "Ports", Key: "8080"}},
		{"add a function like Greet named GreetLoudly", analyze.EditRequest{Kind: analyze.EditAddFunc, SiblingName: "Greet", NewName: "GreetLoudly"}},
		{"add a GreetLoudly function like Greet", analyze.EditRequest{Kind: analyze.EditAddFunc, SiblingName: "Greet", NewName: "GreetLoudly"}},
		{"clone Greet as GreetLoudly", analyze.EditRequest{Kind: analyze.EditAddFunc, SiblingName: "Greet", NewName: "GreetLoudly"}},
		{"add a plum case to Describe.", analyze.EditRequest{Kind: analyze.EditAddCase, FuncName: "Describe", CaseExpr: "plum"}},
	}
	for _, c := range cases {
		got, ok := parseAssembledEdit(c.line)
		if !ok {
			t.Errorf("parseAssembledEdit(%q) not claimed", c.line)
			continue
		}
		if got != c.want {
			t.Errorf("parseAssembledEdit(%q) = %+v, want %+v", c.line, got, c.want)
		}
	}
}

// Sentences owned by other brains — dataflow, where/whatis, the
// getter/test writers, plain chat — must never parse as edits, and
// the flow must not claim them.
func TestParseAssembledEditNonInterference(t *testing.T) {
	for _, line := range []string{
		"where does Items change",
		"what changes Items",
		"where does Items get its data",
		"where does counts come from",
		"where would I add a retry helper",
		"what does Describe do",
		"where is Describe",
		"add a getter for Timeout",
		"add a test for Describe",
		"add a comment to Describe",
		"add an import for fmt",
		"how do I add a case to a switch",
		"add it to the list of things to do",
	} {
		if req, ok := parseAssembledEdit(line); ok {
			t.Errorf("parseAssembledEdit(%q) claimed as %+v — that sentence belongs to another brain", line, req)
		}
		if runAssembledEdit(line, yes) {
			t.Errorf("runAssembledEdit(%q) claimed a non-edit sentence", line)
		}
	}
}

// Yes at the gate: file changes, the new case is really there, and
// the project still stands (the flow built and verified it).
func TestAssembledEditApplyOnYes(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	before := readBack(t, dir, "shop/shop.go")
	if !runAssembledEdit("add a plum case to Describe", yes) {
		t.Fatal("edit sentence not claimed")
	}
	after := readBack(t, dir, "shop/shop.go")
	if after == before {
		t.Fatal("file unchanged after yes — the edit should have been applied and verified")
	}
	if !strings.Contains(after, `case "plum":`) {
		t.Fatalf("new case missing after apply:\n%s", after)
	}
}

// No at the gate: byte-identical, always.
func TestAssembledEditDeclineLeavesBytes(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	before := readBack(t, dir, "shop/shop.go")
	if !runAssembledEdit("add a plum case to Describe", no) {
		t.Fatal("edit sentence not claimed")
	}
	if after := readBack(t, dir, "shop/shop.go"); after != before {
		t.Fatalf("declined edit changed the file:\n%s", after)
	}
}

// A gate read error (EOF on piped stdin) reads as "no".
func TestAssembledEditGateEOFLeavesBytes(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	before := readBack(t, dir, "shop/shop.go")
	runAssembledEdit("add a plum case to Describe", eof)
	if after := readBack(t, dir, "shop/shop.go"); after != before {
		t.Fatal("EOF at the gate must not apply the edit")
	}
}

// A plan that assembles but cannot compile — the new case names a
// value that doesn't exist, in a package the plan imports from a
// sibling file — must roll back byte-identical.
func TestAssembledEditBuildFailureRollsBack(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	before := readBack(t, dir, "shop/shop.go")
	if !runAssembledEdit("add a other.ModeMissing case to ModeName", yes) {
		t.Fatal("edit sentence not claimed")
	}
	if after := readBack(t, dir, "shop/shop.go"); after != before {
		t.Fatalf("build failure must restore the original bytes:\n%s", after)
	}
}

// Generated files are refused before any gate is shown.
func TestAssembledEditGeneratedRefused(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	before := readBack(t, dir, "shop/gen.go")
	asked := false
	runAssembledEdit("add a b case to GeneratedPick", func(string) (string, error) {
		asked = true
		return "y", nil
	})
	if asked {
		t.Fatal("a refused edit must never reach the [y/n] gate")
	}
	if after := readBack(t, dir, "shop/gen.go"); after != before {
		t.Fatal("generated file changed")
	}
}

// Two structs share a name: refuse with candidates, touch nothing.
func TestAssembledEditAmbiguousRefused(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	b1 := readBack(t, dir, "one/one.go")
	b2 := readBack(t, dir, "two/two.go")
	asked := false
	runAssembledEdit("add a Level field of type int to State", func(string) (string, error) {
		asked = true
		return "y", nil
	})
	if asked {
		t.Fatal("an ambiguous edit must never reach the [y/n] gate")
	}
	if readBack(t, dir, "one/one.go") != b1 || readBack(t, dir, "two/two.go") != b2 {
		t.Fatal("ambiguous edit changed a file")
	}
}

// A field edit end to end: the struct gains the field and the
// positional literal gains its zero value, under the one gate.
func TestAssembledEditFieldEndToEnd(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	if !runAssembledEdit("add a Timeout field of type int to Config", yes) {
		t.Fatal("edit sentence not claimed")
	}
	after := readBack(t, dir, "shop/shop.go")
	if !strings.Contains(after, "Timeout int") {
		t.Fatalf("field missing after apply:\n%s", after)
	}
	if !strings.Contains(after, `Config{"localhost", 8080, 0}`) {
		t.Fatalf("positional literal not extended:\n%s", after)
	}
}

// A table registration end to end.
func TestAssembledEditRegisterEndToEnd(t *testing.T) {
	dir := editsChatFixture(t)
	withEditsProject(t, dir)
	if !runAssembledEdit("register thanks in Greetings", yes) {
		t.Fatal("edit sentence not claimed")
	}
	if after := readBack(t, dir, "shop/shop.go"); !strings.Contains(after, `"thanks": "Thanks"`) {
		t.Fatalf("registration missing after apply:\n%s", after)
	}
}
